    s = asils.models.forcemodel.ForceSet_zero();
    s.grav_model = 2;
    s.grav_degree = 6;
    s.has_grav_order = true;
    s.grav_order = 6;
    s.tb_on = true;
    s.tb_model = 0;
    s.tb_nmax = 4;
    s.drag_on = true;
    s.drag_model = 0;
